@page "/chat"
@using sv_3cb8559425904b80994e8294c61a7001.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <div class="main-content @(IsThreadOpen ? "thread-open" : "")">
        @if (_selectedChannel is not null)
        {
            <MessageArea ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         HasMoreMessages="_hasMoreMessages"
                         IsLoadingMore="_isLoadingMore"
                         OnLoadMore="LoadMoreMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (IsThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     ThreadMessages="_threadMessages"
                     OnSendReply="SendThreadReply"
                     OnClose="CloseThread" />
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private bool _hasMoreMessages = true;
    private bool _isLoadingMore;
    private int _skip;

    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];
    private bool IsThreadOpen => _threadRootMessage is not null;

    private CancellationTokenSource _cts = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        var channel = _channels.FirstOrDefault(c => c.Id == channelId);
        if (channel is null) return;

        _selectedChannel = channel;
        _skip = 0;
        _hasMoreMessages = true;
        _messages = [];
        _threadRootMessage = null;
        _threadMessages = [];

        var loaded = await ChatService.GetMessagesAsync(channelId, _skip, PageSize);
        _messages = loaded;
        _skip = loaded.Count;
        _hasMoreMessages = loaded.Count >= PageSize;

        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null || _isLoadingMore || !_hasMoreMessages) return;

        _isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _skip, PageSize);
        _messages.InsertRange(0, older);
        _skip += older.Count;
        _hasMoreMessages = older.Count >= PageSize;
        _isLoadingMore = false;
        BuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;

        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadMessages = await ChatService.GetThreadAsync(messageId);
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(
            _selectedChannel.Id, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);

        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        UpdateReactionLocally(_messages, args.MessageId, args.Emoji);
        UpdateReactionLocally(_threadMessages, args.MessageId, args.Emoji);
    }

    private static void UpdateReactionLocally(List<Message> messages, int messageId, string emoji)
    {
        var idx = messages.FindIndex(m => m.Id == messageId);
        if (idx < 0) return;

        var msg = messages[idx];
        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, ["You"]));
        }
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m =>
            {
                var replies = _messages.Where(r => r.ReplyToId == m.Id).ToList();
                return replies.Count > 0
                    ? new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt))
                    : null;
            })
            .Where(s => s is not null)
            .Cast<ThreadSummary>()
            .ToList();
    }

    public ValueTask DisposeAsync()
    {
        _cts.Cancel();
        _cts.Dispose();
        return ValueTask.CompletedTask;
    }
}

/* ===== Layout ===== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

.main-content {
    flex: 1;
    min-width: 0;
    display: flex;
}

.main-content.thread-open {
    max-width: calc(100% - 20% - 25%);
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #616061;
    font-size: 1.1rem;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #3f0e40;
    color: #fff;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
}

::deep .sidebar-title {
    padding: 16px 16px 8px;
    font-size: 1.1rem;
    font-weight: 700;
    color: #e8e8e8;
}

::deep .channel-list {
    list-style: none;
    margin: 0;
    padding: 0;
}

::deep .channel-item {
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 1px 8px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: rgba(255,255,255,0.1);
}

::deep .channel-item.active {
    background: #1164a3;
}

::deep .channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-desc {
    display: block;
    font-size: 0.75rem;
    color: #cfc3cf;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ===== Message Area ===== */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

::deep .channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
}

::deep .channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

::deep .channel-description {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #616061;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator,
::deep .load-more-btn {
    text-align: center;
    padding: 8px;
    color: #616061;
    font-size: 0.85rem;
}

::deep .load-more-btn {
    background: none;
    border: 1px solid #ddd;
    border-radius: 6px;
    cursor: pointer;
    margin-bottom: 8px;
}

::deep .load-more-btn:hover {
    background: #f8f8f8;
}

/* ===== Message Bubble ===== */
::deep .message-bubble {
    position: relative;
    padding: 6px 12px;
    border-radius: 6px;
    transition: background 0.1s;
}

::deep .message-bubble.hovered {
    background: #f8f8f8;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .author {
    font-weight: 700;
    font-size: 0.95rem;
}

::deep .timestamp {
    font-size: 0.75rem;
    color: #616061;
}

::deep .message-content {
    margin: 2px 0 4px;
    font-size: 0.95rem;
    line-height: 1.46;
    white-space: pre-wrap;
    word-break: break-word;
}

::deep .reactions {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-top: 4px;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border: 1px solid #ddd;
    border-radius: 12px;
    background: #f8f8f8;
    font-size: 0.8rem;
    cursor: pointer;
}

::deep .reaction-badge:hover {
    background: #e8e8f0;
    border-color: #1264a3;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* ===== Message Actions (hover toolbar) ===== */
::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
    z-index: 10;
}

::deep .action-btn {
    background: none;
    border: none;
    padding: 4px 8px;
    cursor: pointer;
    font-size: 0.9rem;
    border-radius: 4px;
}

::deep .action-btn:hover {
    background: #f0f0f0;
}

::deep .emoji-picker {
    position: absolute;
    top: -12px;
    right: 80px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 11;
}

::deep .emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #f0f0f0;
}

/* ===== Message Input ===== */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e8e8e8;
    background: #fff;
}

::deep .message-input textarea {
    flex: 1;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    resize: none;
    outline: none;
}

::deep .message-input textarea:focus {
    border-color: #1264a3;
    box-shadow: 0 0 0 1px #1264a3;
}

::deep .send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 20px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
}

::deep .send-btn:hover:not(:disabled) {
    background: #006b4f;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

/* ===== Thread Panel ===== */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    border-left: 1px solid #e8e8e8;
    display: flex;
    flex-direction: column;
    background: #fff;
}

::deep .thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

::deep .close-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #616061;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #f0f0f0;
}

::deep .thread-root {
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    background: #f8f8f8;
}

::deep .thread-divider {
    padding: 8px 16px;
    font-size: 0.8rem;
    color: #616061;
    border-bottom: 1px solid #e8e8e8;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

