toolArgs.file_text:
/* ===== Layout ===== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

.main-content {
    flex: 1;
    min-width: 0;
    display: flex;
}

.main-content.thread-open {
    max-width: calc(100% - 20% - 25%);
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #616061;
    font-size: 1.1rem;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #3f0e40;
    color: #fff;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
}

::deep .sidebar-title {
    padding: 16px 16px 8px;
    font-size: 1.1rem;
    font-weight: 700;
    color: #e8e8e8;
}

::deep .channel-list {
    list-style: none;
    margin: 0;
    padding: 0;
}

::deep .channel-item {
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 1px 8px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: rgba(255,255,255,0.1);
}

::deep .channel-item.active {
    background: #1164a3;
}

::deep .channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-desc {
    display: block;
    font-size: 0.75rem;
    color: #cfc3cf;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ===== Message Area ===== */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

::deep .channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
}

::deep .channel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

::deep .channel-description {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #616061;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator,
::deep .load-more-btn {
    text-align: center;
    padding: 8px;
    color: #616061;
    font-size: 0.85rem;
}

::deep .load-more-btn {
    background: none;
    border: 1px solid #ddd;
    border-radius: 6px;
    cursor: pointer;
    margin-bottom: 8px;
}

::deep .load-more-btn:hover {
    background: #f8f8f8;
}

/* ===== Message Bubble ===== */
::deep .message-bubble {
    position: relative;
    padding: 6px 12px;
    border-radius: 6px;
    transition: background 0.1s;
}

::deep .message-bubble.hovered {
    background: #f8f8f8;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .author {
    font-weight: 700;
    font-size: 0.95rem;
}

::deep .timestamp {
    font-size: 0.75rem;
    color: #616061;
}

::deep .message-content {
    margin: 2px 0 4px;
    font-size: 0.95rem;
    line-height: 1.46;
    white-space: pre-wrap;
    word-break: break-word;
}

::deep .reactions {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-top: 4px;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border: 1px solid #ddd;
    border-radius: 12px;
    background: #f8f8f8;
    font-size: 0.8rem;
    cursor: pointer;
}

::deep .reaction-badge:hover {
    background: #e8e8f0;
    border-color: #1264a3;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* ===== Message Actions (hover toolbar) ===== */
::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
    z-index: 10;
}

